WITH valid_transactions AS (SELECT *, LENGTH(merchant) AS merchant_length FROM transactions WHERE account_id IN (10, 36) AND (txn_time < '2023-03-01' OR is_flagged)), summary AS (SELECT CASE WHEN YEAR(txn_time) < 2024 THEN 'before_2024' WHEN YEAR(txn_time) = 2024 THEN '2024' ELSE 'after_2024' END AS txn_cohort, ROUND(AVG(amount), 2) AS avg_amount FROM valid_transactions GROUP BY CASE WHEN YEAR(txn_time) < 2024 THEN 'before_2024' WHEN YEAR(txn_time) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT txn_cohort, avg_amount FROM summary;
